-- 90 VERIFY — [GAP358 2026-10-15] GAP 358 조회 전용 (전체 F5, 값 입력 없음)
-- * 기대: V1 마커 1줄 PASS · V2 VALID / 오류 0 / 의존 INVALID 0 · V3 NVL 12줄 PASS / 구 '=' 12줄 0 PASS
-- * V4 (참고) Div 40 최신 ETC Report 버전 자기연결 성립 행 — 구 조건(=) vs 신 조건(NVL '/'): 신 조건 = 전체 행이면 정상
SET LINESIZE 220 PAGESIZE 500
SET DEFINE OFF
SELECT 'V1 마커' CHK, COUNT(*) N, CASE WHEN COUNT(*) = 1 THEN 'PASS' ELSE 'FAIL (미적용 또는 마커 수 불일치)' END JUDGE
  FROM USER_SOURCE WHERE NAME='PKG_DMF0049' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%GAP358 2026-10-15%';
SELECT 'V2 상태' CHK, O.OBJECT_TYPE, O.STATUS, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*) FROM USER_ERRORS E WHERE E.NAME=O.OBJECT_NAME AND E.TYPE=O.OBJECT_TYPE) ERR_CNT,
       (SELECT COUNT(*) FROM USER_OBJECTS X WHERE X.STATUS<>'VALID' AND X.OBJECT_NAME IN (SELECT NAME FROM USER_DEPENDENCIES WHERE REFERENCED_NAME='PKG_DMF0049')) DEP_INVALID
  FROM USER_OBJECTS O WHERE O.OBJECT_NAME='PKG_DMF0049' ORDER BY O.OBJECT_TYPE;
SELECT 'V3 NVL' CHK, COUNT(*) N, CASE WHEN COUNT(*) = 12 THEN 'PASS' ELSE 'FAIL — 회신' END JUDGE
  FROM USER_SOURCE WHERE NAME='PKG_DMF0049' AND TYPE='PACKAGE BODY' AND RTRIM(TEXT, CHR(10)||CHR(13)) IN ('                 AND NVL(A.DIVISION_ID,''/'') = NVL(B.DIVISION_ID,''/'')','                 AND NVL(A.DEPARTMENT_ID,''/'') = NVL(B.DEPARTMENT_ID,''/'')','                 AND NVL(A.DEPT_ID,''/'') = NVL(B.DEPT_ID,''/'')','                 AND NVL(A.ITEM_ID,''/'') = NVL(B.ITEM_ID,''/'')','                 AND NVL(A.MEASURE,''/'') = NVL(B.MEASURE,''/'')','                 AND NVL(A.YYYYMMDD,''/'') = NVL(B.YYYYMMDD,''/'')','                 AND NVL(A.CURRENCY,''/'') = NVL(B.CURRENCY,''/'')','                 AND NVL(A.COMPANY_ID,''/'') = NVL(B.COMPANY_ID,''/'')','                 AND NVL(A.END_CUST_REPORT,''/'') = NVL(B.END_CUST_REPORT,''/'')','                 AND NVL(A.CUST_REPORT,''/'') = NVL(B.CUST_REPORT,''/'')','                 AND NVL(A.PRODUCT_GROUP,''/'') = NVL(B.PRODUCT_GROUP,''/'')','                 AND NVL(A.COUNTRY_CODE,''/'') = NVL(B.COUNTRY_CODE,''/'')')
UNION ALL
SELECT 'V3 구조건', COUNT(*), CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL — 회신' END
  FROM USER_SOURCE WHERE NAME='PKG_DMF0049' AND TYPE='PACKAGE BODY' AND RTRIM(TEXT, CHR(10)||CHR(13)) IN ('                 AND A.DIVISION_ID = B.DIVISION_ID','                 AND A.DEPARTMENT_ID = B.DEPARTMENT_ID','                 AND A.DEPT_ID = B.DEPT_ID','                 AND A.ITEM_ID = B.ITEM_ID','                 AND A.MEASURE = B.MEASURE','                 AND A.YYYYMMDD = B.YYYYMMDD','                 AND A.CURRENCY = B.CURRENCY','                 AND A.COMPANY_ID = B.COMPANY_ID','                 AND A.END_CUST_REPORT = B.END_CUST_REPORT','                 AND A.CUST_REPORT = B.CUST_REPORT','                 AND A.PRODUCT_GROUP = B.PRODUCT_GROUP','                 AND A.COUNTRY_CODE = B.COUNTRY_CODE');
WITH V AS (SELECT MAX(VERSION_NO) VER FROM DM_PLN_SALES_ETC_REPORT_C WHERE DIVISION_ID = '40')
SELECT 'V4 참고' CHK, V.VER,
       (SELECT COUNT(*) FROM DM_PLN_SALES_ETC_REPORT_C WHERE VERSION_NO = V.VER AND DIVISION_ID = '40') TOTAL_ROWS,
       (SELECT COUNT(DISTINCT A.ROWID) FROM DM_PLN_SALES_ETC_REPORT_C A JOIN DM_PLN_SALES_ETC_REPORT_C B
           ON A.VERSION_NO = B.VERSION_NO AND A.DIVISION_ID = B.DIVISION_ID AND A.DEPARTMENT_ID = B.DEPARTMENT_ID AND A.DEPT_ID = B.DEPT_ID AND A.ITEM_ID = B.ITEM_ID AND A.MEASURE = B.MEASURE AND A.YYYYMMDD = B.YYYYMMDD AND A.CURRENCY = B.CURRENCY AND A.COMPANY_ID = B.COMPANY_ID AND A.END_CUST_REPORT = B.END_CUST_REPORT AND A.CUST_REPORT = B.CUST_REPORT AND A.PRODUCT_GROUP = B.PRODUCT_GROUP AND A.COUNTRY_CODE = B.COUNTRY_CODE
         WHERE A.VERSION_NO = V.VER AND A.DIVISION_ID = '40') OLD_EQ_MATCH,
       (SELECT COUNT(DISTINCT A.ROWID) FROM DM_PLN_SALES_ETC_REPORT_C A JOIN DM_PLN_SALES_ETC_REPORT_C B
           ON A.VERSION_NO = B.VERSION_NO AND NVL(A.DIVISION_ID,'/') = NVL(B.DIVISION_ID,'/') AND NVL(A.DEPARTMENT_ID,'/') = NVL(B.DEPARTMENT_ID,'/') AND NVL(A.DEPT_ID,'/') = NVL(B.DEPT_ID,'/') AND NVL(A.ITEM_ID,'/') = NVL(B.ITEM_ID,'/') AND NVL(A.MEASURE,'/') = NVL(B.MEASURE,'/') AND NVL(A.YYYYMMDD,'/') = NVL(B.YYYYMMDD,'/') AND NVL(A.CURRENCY,'/') = NVL(B.CURRENCY,'/') AND NVL(A.COMPANY_ID,'/') = NVL(B.COMPANY_ID,'/') AND NVL(A.END_CUST_REPORT,'/') = NVL(B.END_CUST_REPORT,'/') AND NVL(A.CUST_REPORT,'/') = NVL(B.CUST_REPORT,'/') AND NVL(A.PRODUCT_GROUP,'/') = NVL(B.PRODUCT_GROUP,'/') AND NVL(A.COUNTRY_CODE,'/') = NVL(B.COUNTRY_CODE,'/')
         WHERE A.VERSION_NO = V.VER AND A.DIVISION_ID = '40') NEW_NVL_MATCH
  FROM V;
